import '../../../core/network/api_client.dart';class HealthReport{HealthReport({required this.startDate,required this.endDate,required this.number,required this.average,required this.inRange,required this.trend,required this.stability});factory HealthReport.fromJson(Map<String,dynamic> j)=>HealthReport(startDate:j['startDate'] as String,endDate:j['endDate'] as String,number:j['numberOfReadings'] as int,average:(j['averageGlucose'] as num?)?.toDouble(),inRange:(j['inRangePercentage'] as num?)?.toDouble(),trend:j['trend'] as String,stability:(j['stabilityScore'] as num?)?.toDouble());final String startDate,endDate,trend;final int number;final double? average,inRange,stability;}class HealthReportRepository{HealthReportRepository(this._client);final ApiClient _client;Future<List<HealthReport>>all()async{final r=await _client.dio.get<List<dynamic>>('/api/health-reports');return r.data!.map((e)=>HealthReport.fromJson(e)).toList();}Future<void>create(String start,String end)=>_client.dio.post<void>('/api/health-reports',data:{'startDate':start,'endDate':end});}